const state = await appStore.getState();
const root = appStore && typeof appStore === "object" ? null : null;

const todayKey = () => {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return y + "-" + m + "-" + day;
};

const todayLabel = () => {
  const d = new Date();
  return d.getFullYear() + "年" + (d.getMonth() + 1) + "月" + d.getDate() + "日";
};

const normalizeHabit = (raw) => {
  const item = raw && typeof raw === "object" ? raw : {};
  const doneDates = Array.isArray(item.doneDates)
    ? item.doneDates.filter((x) => typeof x === "string")
    : [];
  return Object.assign({}, item, {
    id: typeof item.id === "string" && item.id ? item.id : "h_" + Math.random().toString(36).slice(2, 10),
    name: typeof item.name === "string" ? item.name : "",
    createdAt: typeof item.createdAt === "string" ? item.createdAt : new Date().toISOString(),
    doneDates: doneDates
  });
};

const readHabits = () => {
  const list = Array.isArray(state.habits) ? state.habits : [];
  return list.map(normalizeHabit);
};

const buildNextState = (habits) => Object.assign({}, state, { habits: habits });

const persist = async (habits) => {
  const next = buildNextState(habits);
  await appStore.setState(next);
  const fresh = await appStore.getState();
  Object.keys(state).forEach((k) => { delete state[k]; });
  Object.assign(state, fresh);
  return readHabits();
};

const el = {
  form: document.querySelector(".habit-form"),
  input: document.querySelector("#habit-name-input"),
  error: document.querySelector(".form-error"),
  list: document.querySelector(".habit-list"),
  emptyTip: document.querySelector(".empty-tip"),
  count: document.querySelector(".list-count"),
  done: document.querySelector(".stat-done"),
  total: document.querySelector(".stat-total"),
  percent: document.querySelector(".stat-percent"),
  date: document.querySelector(".stat-date"),
  backdrop: document.querySelector(".dialog-backdrop"),
  dialogTarget: document.querySelector(".dialog-target"),
  dialogCancel: document.querySelector('.dialog-backdrop [data-action="cancel"]'),
  dialogConfirm: document.querySelector('.dialog-backdrop [data-action="confirm"]')
};

let pendingDeleteId = null;

const render = (habits) => {
  const key = todayKey();
  const total = habits.length;
  const doneCount = habits.filter((h) => h.doneDates.indexOf(key) !== -1).length;

  el.done.textContent = String(doneCount);
  el.total.textContent = String(total);
  el.percent.textContent = total === 0 ? "0%" : Math.round((doneCount / total) * 100) + "%";
  el.date.textContent = todayLabel();
  el.count.textContent = "共 " + total + " 个";

  el.list.textContent = "";
  habits.forEach((habit) => {
    const isDone = habit.doneDates.indexOf(key) !== -1;

    const li = document.createElement("li");
    li.className = "habit-item" + (isDone ? " is-done" : "");
    li.dataset.habitId = habit.id;

    const label = document.createElement("label");
    label.className = "habit-check";

    const box = document.createElement("input");
    box.type = "checkbox";
    box.checked = isDone;
    box.dataset.action = "toggle";
    box.dataset.habitId = habit.id;
    box.setAttribute("aria-label", "标记今天完成：" + habit.name);

    const nameSpan = document.createElement("span");
    nameSpan.className = "habit-name";
    nameSpan.textContent = habit.name;

    label.appendChild(box);
    label.appendChild(nameSpan);

    const meta = document.createElement("span");
    meta.className = "habit-meta";
    meta.textContent = isDone ? "今天已完成" : "今天未完成";

    const del = document.createElement("button");
    del.type = "button";
    del.className = "btn-delete";
    del.textContent = "删除";
    del.dataset.action = "delete";
    del.dataset.habitId = habit.id;

    li.appendChild(label);
    li.appendChild(meta);
    li.appendChild(del);
    el.list.appendChild(li);
  });

  el.emptyTip.hidden = total !== 0;
};

const openDialog = (habit) => {
  pendingDeleteId = habit.id;
  el.dialogTarget.textContent = "习惯：" + habit.name;
  el.backdrop.hidden = false;
  el.dialogConfirm.focus();
};

const closeDialog = () => {
  el.backdrop.hidden = true;
  el.dialogTarget.textContent = "";
};

el.form.addEventListener("submit", async (event) => {
  event.preventDefault();
  const name = el.input.value.trim();
  if (!name) {
    el.error.textContent = "请输入习惯名称。";
    el.input.focus();
    return;
  }
  el.error.textContent = "";
  const habits = readHabits();
  habits.push({
    id: "h_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    name: name,
    createdAt: new Date().toISOString(),
    doneDates: []
  });
  try {
    const saved = await persist(habits);
    el.input.value = "";
    render(saved);
  } catch (err) {
    el.error.textContent = "保存失败，请重试。";
  }
});

el.list.addEventListener("change", async (event) => {
  const target = event.target;
  if (!target || target.dataset.action !== "toggle") return;
  const id = target.dataset.habitId;
  const key = todayKey();
  const habits = readHabits();
  const habit = habits.find((h) => h.id === id);
  if (!habit) return;
  const idx = habit.doneDates.indexOf(key);
  if (idx === -1) {
    habit.doneDates = habit.doneDates.concat([key]);
  } else {
    habit.doneDates = habit.doneDates.filter((d) => d !== key);
  }
  try {
    const saved = await persist(habits);
    render(saved);
  } catch (err) {
    el.error.textContent = "保存失败，请重试。";
    render(readHabits());
  }
});

el.list.addEventListener("click", (event) => {
  const target = event.target;
  if (!target || target.dataset.action !== "delete") return;
  const id = target.dataset.habitId;
  const habit = readHabits().find((h) => h.id === id);
  if (!habit) return;
  openDialog(habit);
});

el.dialogCancel.addEventListener("click", () => {
  pendingDeleteId = null;
  closeDialog();
});

el.dialogConfirm.addEventListener("click", async () => {
  const id = pendingDeleteId;
  if (!id) {
    closeDialog();
    return;
  }
  const habits = readHabits().filter((h) => h.id !== id);
  try {
    const saved = await persist(habits);
    pendingDeleteId = null;
    closeDialog();
    render(saved);
  } catch (err) {
    el.error.textContent = "删除失败，请重试。";
    closeDialog();
  }
});

el.backdrop.addEventListener("click", (event) => {
  if (event.target === el.backdrop) {
    pendingDeleteId = null;
    closeDialog();
  }
});

document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && !el.backdrop.hidden) {
    pendingDeleteId = null;
    closeDialog();
  }
});

render(readHabits());

