:root {
  --bg-deep: #0f1f2e;
  --bg-mid: #16324a;
  --bg-soft: #1d4360;
  --surface: rgba(255, 255, 255, 0.08);
  --surface-strong: rgba(255, 255, 255, 0.14);
  --border-soft: rgba(255, 255, 255, 0.18);
  --text-main: #eaf4ff;
  --text-dim: #a8c2d8;
  --accent: #35d0a5;
  --accent-strong: #1fb98d;
  --danger: #ff6b6b;
  --danger-strong: #e04b4b;
  --radius: 14px;
}

#app {
  min-height: 100vh;
  margin: 0;
  padding: 0;
  background: radial-gradient(circle at 12% 8%, var(--bg-soft) 0%, var(--bg-mid) 42%, var(--bg-deep) 100%);
  background-attachment: fixed;
  color: var(--text-main);
  font-family: "PingFang SC", "Microsoft YaHei", "Helvetica Neue", Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 760px;
  margin: 0 auto;
  padding: 32px 20px 64px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  text-align: center;
  padding: 8px 0 4px;
}

.app-title {
  margin: 0;
  font-size: 30px;
  letter-spacing: 2px;
  color: var(--text-main);
}

.app-subtitle {
  margin: 6px 0 0;
  color: var(--text-dim);
  font-size: 14px;
}

.stats-panel {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.stat-card {
  background: var(--surface);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  backdrop-filter: blur(6px);
}

.stat-main {
  background: linear-gradient(135deg, rgba(53, 208, 165, 0.28), rgba(53, 208, 165, 0.08));
  border-color: rgba(53, 208, 165, 0.45);
}

.stat-label {
  font-size: 13px;
  color: var(--text-dim);
}

.stat-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: 1px;
}

.stat-sep {
  margin: 0 4px;
  color: var(--text-dim);
  font-weight: 400;
}

.stat-percent {
  color: var(--accent);
}

.stat-date {
  font-size: 17px;
  font-weight: 600;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 18px;
  backdrop-filter: blur(6px);
}

.panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.panel-title {
  margin: 0 0 12px;
  font-size: 17px;
  color: var(--text-main);
}

.panel-head .panel-title {
  margin-bottom: 12px;
}

.list-count {
  font-size: 13px;
  color: var(--text-dim);
}

.habit-form {
  display: flex;
  align-items: flex-end;
  gap: 12px;
  flex-wrap: wrap;
}

.field {
  flex: 1 1 220px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 13px;
  color: var(--text-dim);
}

.field-input {
  width: 100%;
  padding: 11px 13px;
  border-radius: 10px;
  border: 1px solid var(--border-soft);
  background: rgba(9, 24, 36, 0.55);
  color: var(--text-main);
  font-size: 15px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field-input::placeholder {
  color: rgba(168, 194, 216, 0.6);
}

.field-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(53, 208, 165, 0.22);
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 11px 18px;
  font-size: 15px;
  font-family: inherit;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.15s ease, border-color 0.15s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--accent);
  color: #06231b;
  font-weight: 700;
}

.btn-primary:hover {
  background: var(--accent-strong);
}

.btn-ghost {
  background: transparent;
  border-color: var(--border-soft);
  color: var(--text-main);
}

.btn-ghost:hover {
  background: var(--surface-strong);
}

.btn-danger {
  background: var(--danger);
  color: #2a0606;
  font-weight: 700;
}

.btn-danger:hover {
  background: var(--danger-strong);
}

.form-error {
  margin: 10px 0 0;
  min-height: 18px;
  font-size: 13px;
  color: var(--danger);
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba(9, 24, 36, 0.4);
  border: 1px solid var(--border-soft);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.habit-item.is-done {
  border-color: rgba(53, 208, 165, 0.6);
  background: rgba(53, 208, 165, 0.14);
}

.habit-check {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 auto;
  cursor: pointer;
  min-width: 0;
}

.habit-check input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
  flex: 0 0 auto;
}

.habit-name {
  font-size: 16px;
  color: var(--text-main);
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: var(--accent);
}

.habit-meta {
  font-size: 12px;
  color: var(--text-dim);
  white-space: nowrap;
}

.btn-delete {
  background: transparent;
  border: 1px solid rgba(255, 107, 107, 0.5);
  color: var(--danger);
  border-radius: 9px;
  padding: 6px 12px;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  flex: 0 0 auto;
}

.btn-delete:hover {
  background: rgba(255, 107, 107, 0.16);
}

.empty-tip {
  margin: 4px 0 0;
  padding: 18px 0;
  text-align: center;
  color: var(--text-dim);
  font-size: 14px;
}

.empty-tip[hidden] {
  display: none;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 12, 20, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: #14304a;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 18px;
  color: var(--text-main);
}

.dialog-text {
  margin: 0;
  font-size: 14px;
  color: var(--text-dim);
}

.dialog-target {
  margin: 10px 0 0;
  padding: 8px 12px;
  border-radius: 9px;
  background: rgba(9, 24, 36, 0.6);
  border: 1px solid var(--border-soft);
  font-size: 14px;
  color: var(--text-main);
  word-break: break-word;
}

.dialog-actions {
  margin-top: 18px;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 560px) {
  .stats-panel {
    grid-template-columns: 1fr 1fr;
  }
  .stat-main {
    grid-column: 1 / -1;
  }
  .habit-form {
    flex-direction: column;
    align-items: stretch;
  }
  .btn-primary {
    width: 100%;
  }
}
